import {keys,sections} from './physics.js';
const num=(v,a,b)=>typeof v==='number'&&Number.isFinite(v)&&v>=a&&v<=b;
export function normalizeModules(modules){if(!Array.isArray(modules)||!modules.length||modules.length>1000)throw Error('El catálogo debe tener entre 1 y 1000 módulos.');return modules.map(m=>{if(!m||typeof m!=='object')throw Error('Registro de módulo no válido.');const o={name:String(m.name??'').slice(0,200),brand:String(m.brand??'').slice(0,120),model:String(m.model??m.name??'').slice(0,180)};for(const k of keys){if(m[k]!==null&&!num(m[k],-1e6,1e6))throw Error(`El campo ${k} debe ser un número o null.`);o[k]=m[k];}o.origin=keys.map((_,i)=>typeof m.origin?.[i]==='string'?m.origin[i]:'Archivo JSON');return o;});}
export function mergeCatalog(a,b){const list=[],equal=(a,b)=>keys.every(k=>(a[k]===null&&b[k]===null)||(a[k]!==null&&b[k]!==null&&Math.abs(a[k]-b[k])<=1e-12*Math.max(1,Math.abs(a[k]),Math.abs(b[k]))));let duplicates=0;for(const m of [...a,...b]){const complete=['Voc','Isc','Vmp','Imp','alpha','beta'].every(k=>m[k]!==null),hit=complete?list.find(n=>equal(m,n)):null;if(hit){duplicates++;if(!hit.brand)hit.brand=m.brand;if(!hit.model)hit.model=m.model;}else list.push(structuredClone(m));}return {modules:list,duplicates};}
export const moduleLabel=m=>[m.brand,m.model||m.name].filter(Boolean).join(' ')||'Módulo sin identificar';
export const catalogFile=modules=>({format:'pv-string-catalog',version:1,coefficientUnits:'1/degC',modules});
export function readCatalog(data){if(data.format!=='pv-string-catalog'||data.version!==1||data.coefficientUnits!=='1/degC')throw Error('Se requiere un catálogo pv-string-catalog v1, con coeficientes en 1/degC.');return normalizeModules(data.modules);}
export function validateField(f){if(!f||!Array.isArray(f.strings)||f.strings.length<1||f.strings.length>24||!Array.isArray(f.boxes)||!f.boxes.length||f.boxes.length>4)throw Error('El campo requiere 1–24 strings y 1–4 stringboxes.');if(typeof f.blocking!=='boolean')throw Error('Bloqueo ideal no válido.');
 const required=(obj,spec)=>{for(const [k,a,b] of spec)if(!num(obj[k],a,b))throw Error(`Valor de ${k} fuera de rango.`);};
 const cable=o=>{required(o,[['length',0,10000],['cableT',-20,120]]);if(!sections.includes(o.section))throw Error('Sección de cable no admitida.');};
 for(const s of f.strings){cable(s);required(s,[['box',0,f.boxes.length-1],['sigmaI',0,15],['sigmaV',0,15],['seed',0,1e9],['tilt',-90,90],['azimuth',0,360],['amplitude',0,45],['period',2,100],['phase',0,360]]);if(!Number.isInteger(s.box)||!Number.isInteger(s.seed)||typeof s.active!=='boolean'||!['manual','soft','roof'].includes(s.mode)||!Array.isArray(s.modules)||s.modules.length<1||s.modules.length>40)throw Error('Configuración de string no válida.');if(Math.abs(s.tilt)+s.amplitude>90&&s.mode==='soft')throw Error('La inclinación del terreno debe permanecer entre −90 y 90°.');for(const d of s.modules){required(d,[['T',-15,85],['G',0,1200],['fI',.55,1.45],['fV',.55,1.45],['transmission',0,1]]);if(!['full','half'].includes(d.layout)||!['A','B'].includes(d.roof)||![0,90].includes(d.rotation)||!['rectangle','triangle'].includes(d.shape)||!Array.isArray(d.shadow)||d.shadow.length!==4||!d.shadow.every(x=>num(x,0,1)))throw Error('Datos de módulo o sombra no válidos.');}}
 f.boxes.forEach(cable);const e=f.env;required(e,[['altitude',0,90],['azimuth',0,360],['dni',0,1200],['dhi',0,500],['albedo',0,1],['tiltA',-90,90],['tiltB',-90,90],['azA',0,360],['azB',0,360],['gA',0,1200],['gB',0,1200]]);if(!['solar','fixed'].includes(e.roofMethod))throw Error('Método de irradiancia no válido.');return f;}
